// Original, constrained syntax exercises. Only the marked blank is submitted;
// open implementation and executable I/O tests belong to Challenge.
import { CPP_SKILL_QUIZZES, RUST_SKILL_QUIZZES } from './skillquizdata/cpprust.01433282f010fff3.js';
import { CSHARP_SKILL_QUIZZES, JAVA_SKILL_QUIZZES } from './skillquizdata/csharpjava.01433282f010fff3.js';
import { GO_SKILL_QUIZZES, PYTHON_SKILL_QUIZZES } from './skillquizdata/go-python.01433282f010fff3.js';
import { LUA_SKILL_QUIZZES, SQL_SKILL_QUIZZES } from './skillquizdata/lua-sql.01433282f010fff3.js';

export const SKILL_QUIZ_VERSION = 1;
export const SKILL_QUIZ_ANSWER_LIMIT = 4096;
export const SKILL_QUIZ_LANGUAGES = Object.freeze(['cpp','csharp','rust','go','python','java','sql','lua']);
export const SKILL_QUIZ_SUBJECTS = Object.freeze(['syntax','design','graphics','systems']);
export const SKILL_QUIZ_DIFFICULTIES = Object.freeze(['入門','基礎','応用','発展']);
const banks = {cpp:CPP_SKILL_QUIZZES,csharp:CSHARP_SKILL_QUIZZES,rust:RUST_SKILL_QUIZZES,go:GO_SKILL_QUIZZES,python:PYTHON_SKILL_QUIZZES,java:JAVA_SKILL_QUIZZES,sql:SQL_SKILL_QUIZZES,lua:LUA_SKILL_QUIZZES};
const catalog = [], lookup = new Map(), pools = new Map();
for (const language of SKILL_QUIZ_LANGUAGES) {
  for (const subject of SKILL_QUIZ_SUBJECTS) {
    const pool = banks[language].filter(q=>q.subject===subject).map((raw,index)=>{
      const id=`skill-quiz/v${SKILL_QUIZ_VERSION}/${language}/${raw.id}`;
      const q={...raw,id,localId:raw.id,kind:'skill-quiz',version:SKILL_QUIZ_VERSION,language,subject,index,estimatedMinutes:raw.minutes,
        difficultyLabel:SKILL_QUIZ_DIFFICULTIES[raw.difficulty-1],
        prerequisites:(raw.prerequisites || []).map(ref=>`skill-quiz/v${SKILL_QUIZ_VERSION}/${language}/${ref}`)};
      if(lookup.has(id))throw new Error(`Duplicate syntax quiz: ${id}`);
      lookup.set(id,q);catalog.push(q);return q;
    });
    pools.set(`${language}/${subject}`,pool);
  }
}
export const skillQuizCatalog = () => [...catalog];
export const skillQuizById = id => typeof id==='string' ? lookup.get(id) || null : null;
export const skillQuizTopics = (language,subject) => [...(pools.get(`${language}/${subject}`) || [])];
export function skillQuizAt(language,subject,index=0) {
  const pool=pools.get(`${language}/${subject}`);
  if(!pool?.length)return null;
  const n=Number.isSafeInteger(index) && index>=0?index:0;
  return pool[n%pool.length];
}

// Compare complete lexical tokens, never a keyword substring. Whitespace may
// separate tokens, but cannot split an identifier or change a string literal.
export function skillQuizTokens(source,language) {
  if(typeof source!=='string' || source.length>SKILL_QUIZ_ANSWER_LIMIT)return null;
  const tokens=[];
  let i=0;
  while(i<source.length){
    const rest=source.slice(i),space=/^\s+/.exec(rest);
    if(space){i+=space[0].length;continue;}
    if((language==='python' && rest[0]==='#') || (['lua','sql'].includes(language) && rest.startsWith('--')) || (!['python','lua','sql'].includes(language) && rest.startsWith('//')) || (['cpp','csharp','rust','go','java','sql'].includes(language) && rest.startsWith('/*')))return null;
    const quote=rest[0];
    // Rust lifetime names are not character literals.
    const lifetime=language==='rust' && /^'[A-Za-z_][A-Za-z_0-9]*/.exec(rest);
    if(lifetime && rest[lifetime[0].length]!=="'"){tokens.push(lifetime[0]);i+=lifetime[0].length;continue;}
    if(quote==='"'||quote==="'"||quote==='`'){
      let end=i+1,closed=false;
      for(;end<source.length;end++){
        if(source[end]==='\\' && quote!=='`'){end++;continue;}
        if(source[end]===quote){
          if(language==='sql' && source[end+1]===quote){end++;continue;}
          end++;closed=true;break;
        }
      }
      if(!closed)return null;
      tokens.push(source.slice(i,end));i=end;continue;
    }
    const token=/^(?:[A-Za-z_$][A-Za-z_0-9$]*|(?:0[xX][\da-fA-F_]+|\d[\d_]*(?:\.\d[\d_]*)?(?:[eE][+-]?\d+)?)(?:[A-Za-z_][A-Za-z_0-9]*)?|<=>|>>=|<<=|\?\?=|\.\.=|\.\.\.|::|=>|->|\?\?|\?\.|:=|<-|\*\*|\/\/|==|!=|<=|>=|&&|\|\||\+\+|--|\+=|-=|\*=|\/=|%=|&=|\|=|\^=|<<|>>|\.\.|[^\s])/.exec(rest);
    if(!token)return null;
    const value=token[0];tokens.push(language==='sql' && /^[A-Za-z_]/.test(value)?value.toUpperCase():value);i+=value.length;
  }
  return tokens;
}
export function gradeSkillQuiz(quiz,answer) {
  const actual=skillQuizTokens(answer,quiz?.language);
  const accepted=quiz && [quiz.answer,...(quiz.alternatives || [])];
  const passed=!!actual?.length && !!accepted?.some(value=>{
    const expected=skillQuizTokens(value,quiz.language);
    return expected?.length===actual.length && expected.every((token,index)=>token===actual[index]);
  });
  return {passed,status:passed?'passed':'failed',message:passed?'空欄の条件を満たしています。':'空欄の条件と前後の処理を確認してください。',
    explanation:quiz?.explanation || '',completedSource:passed?quiz.code.replace('____',answer):null};
}
